function [ra, dec] = sun_radec(mjd)
%SUN_RADEC  sun_radec of jb2008_density.m: the low-precision Sun's right ascension and declination [rad] (mean equinox of
%   date) at an MJD.
%   mjd: real[1] (passed a plain number)
